package config

import v1 "k8s.io/api/core/v1"

// Validator contains validator specification
type Validator struct {
	// The validator name.
	// +optional
	Name string

	// The validator description.
	// +optional
	Description string

	// A link to the documentation where the requirements are defined.
	// +optional
	Documentation string

	// A list of checks to perform validation against.
	Checks []Check

	// A list of environment variables to set on the container before starting.
	Env []v1.EnvVar

	// A list of ports to expose on the container.
	Ports []v1.ServicePort

	// A list of volumes to mount on the container.
	Volumes []Volume

	// A command to run in the container
	// +optional
	Command []string

	// Additional flags to pass to the docker CLI.
	// +optional
	DockerRunOptions []string  `yaml:"dockerRunOptions"`
}

type Check struct {
	// The check name.
	// +optional
	Name string

	// The check description.
	// +optional
	Description string

	// A probe to run.
	Probe Probe
}

type Probe struct {
	InitialDelaySeconds int `yaml:"initialDelaySeconds"`

	TimeoutSeconds int `yaml:"timeoutSeconds"`

	PeriodSeconds int `yaml:"periodSeconds"`

	SuccessThreshold int `yaml:"successThreshold"`

	FailureThreshold int `yaml:"failureThreshold"`

	TerminationGracePeriodSeconds int `yaml:"terminationGracePeriodSeconds"`

	Exec *v1.ExecAction `yaml:"exec"`

	HTTPGet *HTTPGetAction `yaml:"httpGet"`

	TCPSocket *TCPSocketAction `yaml:"tcpSocket" `
}

func (p *Probe) UnmarshalYAML(unmarshal func(interface{}) error) error {
	type rawProbe Probe
	raw := rawProbe{
		InitialDelaySeconds:           0,
		TimeoutSeconds:                30,
		PeriodSeconds:                 1,
		SuccessThreshold:              1,
		FailureThreshold:              1,
		TerminationGracePeriodSeconds: 30,
	}
	if err := unmarshal(&raw); err != nil {
		return err
	}

	*p = Probe(raw)
	return nil
}

type HTTPGetAction struct {
	// Path to access on the HTTP server.
	// +optional
	Path string `yaml:"path,omitempty"`
	// Number of the port to access on the container.
	// Number must be in the range 1 to 65535.
	Port int `yaml:"port"`
	// Scheme to use for connecting to the host.
	// Defaults to HTTP.
	// +optional
	Scheme v1.URIScheme `yaml:"scheme,omitempty"`
	// Custom headers to set in the request. HTTP allows repeated headers.
	// +optional
	HTTPHeaders []v1.HTTPHeader `yaml:"httpHeaders,omitempty"`
	// Headers expected in the response. Check will fail if any are missing.
	// +optional
	ResponseHTTPHeaders []v1.HTTPHeader `yaml:"responseHttpHeaders,omitempty"`
}

type TCPSocketAction struct {
	// Number or name of the port to access on the container.
	// Number must be in the range 1 to 65535.
	Port int `yaml:"port"`
}

type Volume struct {
	// Path to mount in the container
	MountPath string `yaml:"mountPath,omitempty"`

	// Path to mount from host, will use empty volume if omitted
	// +optional
	Path string `yaml:"path,omitempty"`
}

package schema

import (
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestSchemaCompilesAndExamplesValidate(t *testing.T) {
	root := filepath.Join("..", "..")
	sch, err := Compile(filepath.Join(root, Path))
	require.NoError(t, err)

	examples, err := filepath.Glob(filepath.Join(root, "examples", "*.yaml"))
	require.NoError(t, err)
	require.NotEmpty(t, examples)
	for _, example := range examples {
		err := ValidateFile(filepath.Join(root, Path), example)
		require.NoError(t, err, example)
	}

	require.NotNil(t, sch)
}

package schema

import (
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestCopiedKubernetesFieldsExplainHowToAdapt(t *testing.T) {
	root := filepath.Join("..", "..")
	schemaPath := filepath.Join(root, Path)

	tests := []struct {
		name    string
		fixture string
		message string
	}{
		{"EnvVar valueFrom", "kubernetes-env-value-from.yaml", "env[0].valueFrom is a Kubernetes core/v1.EnvVar field, but Container Canary supports only name and value"},
		{"gRPC probe", "kubernetes-grpc.yaml", "checks[0].probe.grpc is a Kubernetes probe action, but it is unsupported in container-canary.nvidia.com/v1; use exec, httpGet, or tcpSocket"},
		{"Pod probe", "kubernetes-liveness-probe.yaml", "livenessProbe is a Kubernetes Pod field; Container Canary uses checks[].probe instead"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := ValidateFile(schemaPath, filepath.Join("testdata", tt.fixture))
			assert.EqualError(t, err, tt.message)
		})
	}
}

